//! Synthetic support-closure and applicability counterexamples. No provider,
//! labels, archived model review or source-truth certification is used here.
use lightog_core::{
    common::{canonical_hash as hash, sha, text_sha},
    knowledge_build, semantic_review_v4 as review, support_selection,
};
use serde_json::{json, Value};
fn fixture() -> Value {
    let text="🚀 Mode Alpha.\nIt leaves the index unchanged.\nIt refers to mode Alpha.\nIf the same file is unstaged, abort.\n";
    let digest = sha(&json!(text));
    let size = text.encode_utf16().count();
    let snapshot = json!({"base_ref":"support_v2_authored","source_epoch":0,"graph_revision":null,"sources":[{"source_ref":"src","source_revision":"r1","original_sha256":digest,"text_sha256":digest,"parser_version":"authored/1"}]});
    let mut at = 0;
    let fragments:Vec<_>=text.split_inclusive('\n').zip(["mode","assertion","antecedent","condition"]).map(|(quote,id)|{let start=at;at+=quote.encode_utf16().count();json!({"id":id,"origin":"SOURCE_FRAGMENT","source_ref":"src","source_revision":"r1","block_ref":"b","text_sha256":digest,"span":{"start":start,"end":at,"quote":quote,"offset_unit":"utf16_code_unit"},"claim_refs":[],"role":"PRIMARY"})}).collect();
    let es = json!({"contract_version":"lightog-demand/0.1","evidence_set_id":"es","snapshot":snapshot,"fragments":fragments});
    let ctx = json!({"examples":{"es":es},"source_texts":[{"source_ref":"src","source_revision":"r1","text":text,"original_sha256":digest,"parser_version":"authored/1","blocks":[{"block_ref":"b","start":0,"end":size}]}],"authority":{"requests":[],"allowed_snapshots":[snapshot],"claims":[],"receipts":[],"scope_bindings":[],"entities":[],"predicate_refs":[],"user_definitions":[],"groups":[],"entity_links":[]}});
    let prepared=knowledge_build::prepare_extract(&json!({"evidence_set_ref":"es","cq_guidance":"Authored mode behavior","trusted_context":ctx})).unwrap();
    let raw = json!({"entities":[{"local_id":"Alpha","surface":"Alpha","type_label":null,"mention_evidence_id":"mode"}],"candidates":[{"kind":"ATTRIBUTE","subject_local_id":"Alpha","predicate":{"label":"index effect","description":"Effect on index state","evidence_ids":["assertion"]},"object":{"entity_local_id":null,"typed_value":{"kind":"STRING","value":"unchanged"}},"direction":"NONE","description":"Mode Alpha leaves the index unchanged.","keywords":["index"],"qualifiers":{"scope":"Mode Alpha","modality":"REPORTED","negated":false,"unit":null,"effective_time":null},"conditions":[],"support_roles":{"assertion":["assertion"],"subject_scope":["mode"],"antecedent":["antecedent"],"condition":[]}}]});
    json!({"prepared":prepared,"trusted_context":ctx,"raw":raw,"unit_id":"synthetic_support_v2","max_candidates":8})
}
fn material(p: &Value) -> Value {
    let mut p = p.clone();
    for e in p["raw"]["entities"].as_array_mut().unwrap() {
        e["mention_occurrence"] = json!(1);
    }
    support_selection::execute("materialize_required_occurrence_v1", &p).unwrap()
}
fn proposal(p: &Value) -> Value {
    let m = material(p);
    assert_eq!(m["candidates"].as_array().unwrap().len(), 1);
    json!({"contract_version":review::VERSION,"candidates":m["candidates"],"prepared":p["prepared"],"trusted_context":p["trusted_context"],"receipts":m["receipts"],"context_evidence_ids":["mode","assertion","antecedent","condition"],"max_context_utf16":12000})
}
fn judgment(decision:&str)->Value{json!({"decision":decision,"reason":"Authored synthetic model judgment, never a semantic certificate.","evidence_ids":["assertion","mode","antecedent"]})}
fn output(q:&Value,role:&str)->Value{serde_json::from_str(q[role]["raw_output"].as_str().unwrap()).unwrap()}
fn rebind(q:&mut Value,role:&str,v:Value){let raw=serde_json::to_string(&v).unwrap();q[role]["raw_output"]=json!(raw);q[role]["review_provenance"]["review_output_sha256"]=json!(hash(&v));q[role]["review_provenance"]["raw_output_sha256"]=json!(text_sha(&raw));}
fn complete(f:&Value)->Value{let mut q=proposal(f);let ready=review::execute("prepare",&q).unwrap();q["manifest"]=ready["manifest"].clone();for(role,key)in[("structure","structure_review"),("narrative","narrative_review")]{let rows:Vec<_>=ready[role]["review_view"].as_array().unwrap().iter().map(|v|{let mut row=json!({"candidate_id":v["candidate_id"],"decision":"SUPPORTED","readback":v["readback_expectation"]});if role=="structure"{let dims:serde_json::Map<_,_>=review::DIMENSIONS.iter().map(|d|((*d).to_owned(),judgment(if *d=="units"{"NOT_APPLICABLE"}else{"SUPPORTED"}))).collect();row["dimensions"]=json!(dims);}else{row["description_support"]=judgment("SUPPORTED");row["condition_exception_fidelity"]=judgment("SUPPORTED");row["structure_description_consistency"]=judgment("CONSISTENT");}row}).collect();let parsed=json!({"reviews":rows});let raw=serde_json::to_string(&parsed).unwrap();q[key]=json!({"manifest":ready[role]["manifest"],"raw_output":raw,"review_provenance":{"origin":"SYNTHETIC","review_request_id":format!("review-{role}"),"proposal_request_ids":["proposal"],"review_output_sha256":hash(&parsed),"raw_output_sha256":text_sha(&raw),"model":"authored-split-fixture","config_revision":1}});}q}
#[test]fn stage_views_are_separate_and_keep_nested_semantics(){let f=fixture();let q=proposal(&f);let p=review::execute("prepare",&q).unwrap();let av=&p["structure"]["review_view"][0];assert!(av.get("narrative_to_check").is_none());assert!(av["structural_atom"].get("description").is_none());assert!(av["structural_atom"].get("keywords").is_none());assert!(av["readback_expectation"].get("description_sha256").is_none());assert_eq!(av["structural_atom"]["predicate"],q["candidates"][0]["predicate"]);assert_eq!(av["structural_atom"]["object"],q["candidates"][0]["object"]);assert_eq!(p["narrative"]["review_view"][0]["narrative_to_check"]["description"],q["candidates"][0]["description"]);assert_eq!(review::execute("prepare_structure",&q).unwrap(),p["structure"]);assert_eq!(review::execute("prepare_narrative",&q).unwrap(),p["narrative"]);assert_ne!(p["structure"]["manifest"],p["narrative"]["manifest"]);let mut leaked=q;leaked["structure_review"]=json!({"old_verdict":"SUPPORTED"});assert!(review::execute("prepare_narrative",&leaked).is_err());}
#[test]fn full_separate_raw_and_provenance_remain_in_receipt(){let q=complete(&fixture());let p=review::execute("apply",&q).unwrap();assert_eq!(p["eligible_candidates"].as_array().unwrap().len(),1);assert_eq!(p["semantic_support_certified"],false);assert_ne!(p["review_origin"],"FRESH_MODEL");for role in ["structure_review","narrative_review"]{assert_eq!(p["review_receipt"][role]["raw_output"],q[role]["raw_output"]);assert_eq!(p["review_receipt"][role]["review_provenance"],q[role]["review_provenance"]);}let mut only=proposal(&fixture());only["manifest"]=q["manifest"].clone();only["structure_review"]=q["structure_review"].clone();assert_eq!(review::execute("validate_structure",&only).unwrap()["structure_supported_candidate_ids"].as_array().unwrap().len(),1);}
#[test]fn missing_side_same_request_or_proposal_context_rejected(){for role in ["structure_review","narrative_review"]{let mut q=complete(&fixture());q.as_object_mut().unwrap().remove(role);assert!(review::execute("apply",&q).is_err());}for mode in 0..3{let mut q=complete(&fixture());match mode{0=>q["narrative_review"]["review_provenance"]["review_request_id"]=q["structure_review"]["review_provenance"]["review_request_id"].clone(),1=>q["structure_review"]["review_provenance"]["review_request_id"]=json!("proposal"),_=>q["narrative_review"]["review_provenance"]["proposal_request_ids"]=json!(["different-proposal"])}assert_eq!(review::execute("apply",&q).unwrap_err().code,"SPLIT_REVIEW_NOT_INDEPENDENT");}}
#[test]fn every_raw_parsed_manifest_and_readback_binding_is_replayed(){for role in ["structure_review","narrative_review"]{for mode in 0..5{let mut q=complete(&fixture());match mode{0=>q[role]["review_provenance"]["review_output_sha256"]=json!("0".repeat(64)),1=>q[role]["review_provenance"]["raw_output_sha256"]=json!("0".repeat(64)),2=>q[role]["manifest"]["review_view_sha256"]=json!("0".repeat(64)),3=>{let mut v=output(&q,role);v["reviews"][0]["readback"]["structure_field_sha256"]["predicate"]=json!("0".repeat(64));rebind(&mut q,role,v);},_=>q[role]["raw_output"]=json!(format!("{} ",q[role]["raw_output"].as_str().unwrap()))}assert!(review::execute("apply",&q).is_err(),"{role} {mode}");}}let mut q=complete(&fixture());q["trusted_context"]["source_texts"][0]["text"]=json!("Source drift");assert!(review::execute("apply",&q).is_err());}
#[test]fn incomplete_duplicate_or_trailing_raw_is_not_repaired(){for raw in ["{\"reviews\":[", "{\"reviews\":[],\"reviews\":[]}","{\"reviews\":[]} {}"]{let mut q=complete(&fixture());q["structure_review"]["raw_output"]=json!(raw);q["structure_review"]["review_provenance"]["raw_output_sha256"]=json!(text_sha(raw));assert!(review::execute("apply",&q).is_err());}}
#[test]fn all_structural_dimensions_are_vetoes_even_when_narrative_passes(){for d in review::DIMENSIONS{let mut q=complete(&fixture());let mut v=output(&q,"structure_review");v["reviews"][0]["dimensions"][d]["decision"]=json!("UNSUPPORTED");rebind(&mut q,"structure_review",v);assert!(review::execute("apply",&q).unwrap()["eligible_candidates"].as_array().unwrap().is_empty(),"{d}");}}
#[test]fn missing_condition_exception_or_narrative_consistency_is_held(){for(field,decision)in[("description_support","PARTIAL"),("condition_exception_fidelity","PARTIAL"),("condition_exception_fidelity","UNSUPPORTED"),("condition_exception_fidelity","UNKNOWN"),("structure_description_consistency","CONFLICT")]{let mut q=complete(&fixture());let mut v=output(&q,"narrative_review");v["reviews"][0][field]["decision"]=json!(decision);rebind(&mut q,"narrative_review",v);assert!(review::execute("apply",&q).unwrap()["eligible_candidates"].as_array().unwrap().is_empty());}}
#[test]fn own_support_and_not_applicable_guards_are_not_weakened(){let mut f=fixture();f["raw"]["candidates"][0]["support_roles"]["subject_scope"]=json!([]);f["raw"]["candidates"][0]["support_roles"]["antecedent"]=json!([]);let q=complete(&f);assert!(review::execute("apply",&q).unwrap()["eligible_candidates"].as_array().unwrap().is_empty(),"an assertion cannot launder an unselected anchor as positive support");let mut f=fixture();f["raw"]["candidates"][0]["qualifiers"]["unit"]=json!("days");assert!(review::execute("apply",&complete(&f)).unwrap()["eligible_candidates"].as_array().unwrap().is_empty());}
#[test]fn two_wrong_but_bound_authored_judgments_still_cannot_be_called_a_truth_certificate(){let mut f=fixture();f["raw"]["candidates"][0]["qualifiers"]["negated"]=json!(true);let out=review::execute("apply",&complete(&f)).unwrap();assert_eq!(out["eligible_candidates"].as_array().unwrap().len(),1);assert_eq!(out["semantic_support_certified"],false,"the kernel cannot discover that both authored semantic judgments are wrong");}
fn learning_payload(f:&Value,j:&Value,runtime:&Value)->Value{let mut rt=runtime.clone();rt["persisted_job_sha256"]=j["job_sha256"].clone();rt["persisted_revision"]=j["revision"].clone();json!({"contract_version":lightog_core::source_learning_v1::VERSION,"job":j,"context":f["trusted_context"],"runtime":rt})}
fn commit_payload(f:&Value,gate:&Value,policy:&str,with_attempts:bool)->Value{use lightog_core::source_learning_v1 as l;let es=&f["trusted_context"]["examples"]["es"];let question="Review authored Alpha mode evidence";let runtime=json!({"current_snapshot":es["snapshot"],"grants":[{"request_ref":"req_split","question_sha256":text_sha(question),"base_ref":es["snapshot"]["base_ref"],"source_epoch":0,"access_mode":"LEARN","learning_requested":true}],"persisted_job_sha256":null,"persisted_revision":0,"support_hold_candidate_sha256":[],"graph_record_sha256":null,"commit_record_sha256":null,"index_record_sha256":null,"index_payload_sha256":null});let create=json!({"contract_version":l::VERSION,"request":{"request_ref":"req_split","raw_question":question,"cq_seeds":[],"kind":"DISCOVERY","policy_version":policy},"evidence_set":es,"source_gap":null,"context":f["trusted_context"],"runtime":runtime});let mut j=l::execute("create",&create).unwrap()["job"].clone();for stage in ["RETRIEVING","EXTRACTING","VALIDATING"]{let mut p=learning_payload(f,&j,&runtime);p["next_stage"]=json!(stage);j=l::execute("step",&p).unwrap()["job"].clone();}if with_attempts{for (phase,id) in [("EXTRACTION","proposal"),("SEMANTIC_STRUCTURE_REVIEW","review-structure"),("SEMANTIC_NARRATIVE_REVIEW","review-narrative")]{let mut p=learning_payload(f,&j,&runtime);p["attempt_id"]=json!(id);p["phase"]=json!(phase);p["request_sha256"]=json!(hash(&json!({"synthetic_phase":phase})));j=l::execute("begin_attempt",&p).unwrap()["job"].clone();let mut p=learning_payload(f,&j,&runtime);p["attempt_id"]=json!(id);p["outcome"]=json!("RETURNED");p["request_id"]=json!(id);p["response_sha256"]=json!(hash(&json!({"synthetic_returned":phase})));j=l::execute("finish_attempt",&p).unwrap()["job"].clone();}}let mut p=learning_payload(f,&j,&runtime);p["gate_input"]=gate.clone();p["base_graph"]=Value::Null;p}
#[test]fn split_learning_policy_requires_dual_v4_and_durable_returned_attempts(){use lightog_core::source_learning_v1 as l;let f=fixture();let gate=complete(&f);for policy in ["source-learning-product-split-review-v1","source-learning-product-rebuild-split-review-v1"]{let missing=commit_payload(&f,&gate,policy,false);assert_eq!(l::execute("prepare_commit",&missing).unwrap_err().code,"SOURCE_LEARNING_SPLIT_RETURNED_ATTEMPTS_REQUIRED");let mut p=commit_payload(&f,&gate,policy,true);assert!(l::execute("prepare_commit",&p).is_ok());p["gate_input"]["narrative_review"]["review_provenance"]["review_request_id"]=json!("invented-different-review");assert_eq!(l::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_SPLIT_ATTEMPT_BINDING_INVALID");}}
#[test]fn old_learning_policies_do_not_accept_v4_as_a_legacy_review(){use lightog_core::source_learning_v1 as l;let f=fixture();for policy in ["source-learning-product-required-occurrence-v1","source-learning-product-structured-review-v1"]{assert_eq!(l::execute("prepare_commit",&commit_payload(&f,&complete(&f),policy,true)).unwrap_err().code,"SOURCE_LEARNING_GATE_BINDING_INVALID");}}
#[test]fn split_policy_rejects_legacy_gate_and_stripped_required_profile(){use lightog_core::source_learning_v1 as l;let f=fixture();let q=complete(&f);for policy in ["source-learning-product-split-review-v1","source-learning-product-rebuild-split-review-v1"]{let mut p=commit_payload(&f,&q,policy,true);p["gate_input"]["contract_version"]=json!("lightog-semantic-review/0.3");assert_eq!(l::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_GATE_BINDING_INVALID");let mut p=commit_payload(&f,&q,policy,true);p["gate_input"]["manifest"].as_object_mut().unwrap().remove("proposal_contract_version");assert_eq!(l::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_REQUIRED_PROPOSAL_CONTRACT");let mut p=commit_payload(&f,&q,policy,true);for r in p["gate_input"]["receipts"].as_array_mut().unwrap(){for k in ["proposal_contract_version","proposal_contract_profile","proposal_contract_profile_sha256"]{r.as_object_mut().unwrap().remove(k);}}assert_eq!(l::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_REQUIRED_PROPOSAL_CONTRACT");}}
#[test]fn positive_reference_schema_rejects_empty_supported_conditions_and_units_na(){let q=complete(&fixture());let ready=review::execute("prepare",&proposal(&fixture())).unwrap();let schema=&ready["structure"]["review_output_schema"];let validator=jsonschema::validator_for(schema).unwrap();assert!(validator.is_valid(&output(&q,"structure_review")));for dim in ["conditions","units"]{let mut raw=output(&q,"structure_review");raw["reviews"][0]["dimensions"][dim]["evidence_ids"]=json!([]);assert!(!validator.is_valid(&raw),"positive {dim} must declare source refs in model schema");assert_eq!(schema["properties"]["reviews"]["items"]["properties"]["dimensions"]["properties"][dim]["allOf"][0]["then"]["properties"]["evidence_ids"]["minItems"],1);}}
#[test]fn positive_reference_schema_covers_narrative_support_fidelity_and_consistency(){let q=complete(&fixture());let ready=review::execute("prepare",&proposal(&fixture())).unwrap();let validator=jsonschema::validator_for(&ready["narrative"]["review_output_schema"]).unwrap();for key in ["description_support","condition_exception_fidelity","structure_description_consistency"]{let mut raw=output(&q,"narrative_review");raw["reviews"][0][key]["evidence_ids"]=json!([]);assert!(!validator.is_valid(&raw),"positive {key} cannot omit refs");raw["reviews"][0][key]["decision"]=json!(if key=="structure_description_consistency"{"CONFLICT"}else{"UNSUPPORTED"});assert!(validator.is_valid(&raw),"negative {key} with empty refs remains legal");}}
#[test]fn positive_empty_refs_still_hold_at_runtime_and_negative_empty_is_valid_schema(){let q=complete(&fixture());let ready=review::execute("prepare",&proposal(&fixture())).unwrap();for(role,field)in[("structure_review","conditions"),("narrative_review","condition_exception_fidelity")]{let mut p=q.clone();let mut raw=output(&p,role);if role=="structure_review"{raw["reviews"][0]["dimensions"][field]["evidence_ids"]=json!([]);}else{raw["reviews"][0][field]["evidence_ids"]=json!([]);}rebind(&mut p,role,raw.clone());assert!(review::execute("apply",&p).unwrap()["eligible_candidates"].as_array().unwrap().is_empty(),"runtime must not invent citations");if role=="structure_review"{raw["reviews"][0]["dimensions"][field]["decision"]=json!("UNSUPPORTED");}else{raw["reviews"][0][field]["decision"]=json!("PARTIAL");}let schema=&ready[if role=="structure_review"{"structure"}else{"narrative"}]["review_output_schema"];assert!(jsonschema::validator_for(schema).unwrap().is_valid(&raw));}}
#[test]fn strict_io_policy_keeps_required_dual_review_and_three_returned_bindings(){use lightog_core::source_learning_v1 as l;let f=fixture();let q=complete(&f);for policy in ["source-learning-product-split-strict-review-v1","source-learning-product-rebuild-split-strict-review-v1"]{assert!(l::execute("prepare_commit",&commit_payload(&f,&q,policy,true)).is_ok());assert_eq!(l::execute("prepare_commit",&commit_payload(&f,&q,policy,false)).unwrap_err().code,"SOURCE_LEARNING_SPLIT_RETURNED_ATTEMPTS_REQUIRED");let mut p=commit_payload(&f,&q,policy,true);p["gate_input"]["manifest"].as_object_mut().unwrap().remove("proposal_contract_version");assert_eq!(l::execute("prepare_commit",&p).unwrap_err().code,"SOURCE_LEARNING_REQUIRED_PROPOSAL_CONTRACT");}}
#[test]fn duplicate_evidence_ids_still_fail_in_unchanged_local_gate(){let mut p=complete(&fixture());let mut raw=output(&p,"structure_review");raw["reviews"][0]["dimensions"]["conditions"]["evidence_ids"]=json!(["assertion","assertion"]);rebind(&mut p,"structure_review",raw);assert_eq!(review::execute("apply",&p).unwrap_err().code,"SPLIT_REVIEW_EVIDENCE_INVALID");}
